'use client';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useEffect, useState } from 'react';
import { useLanguage } from '../lib/LanguageContext';
import ThemeToggle from './ThemeToggle';

// Only links that lead somewhere real. Add Projects / Services / Trust here once those pages exist.
const NAV = [
  { href: '/', key: 'nav.home' },
  { href: '/#features', key: 'nav.features' },
  { href: '/#how-it-works', key: 'nav.how' },
  { href: '/#credential', key: 'nav.credential' },
];

function LangSwitch() {
  const { language, changeLanguage, t, LANGUAGES } = useLanguage();
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (!open) return;
    const onClick = (e) => { if (!e.target.closest('.lang-switch')) setOpen(false); };
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('click', onClick);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('click', onClick);
      document.removeEventListener('keydown', onKey);
    };
  }, [open]);

  return (
    <div className="lang-switch">
      <button type="button" className="lang-btn" aria-label={t('nav.language')} aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(!open)}>
        <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" /><path d="M3 12h18M12 3c2.5 2.7 3.8 5.7 3.8 9s-1.3 6.3-3.8 9c-2.5-2.7-3.8-5.7-3.8-9S9.5 5.7 12 3z" /></svg>
        <span>{language.toUpperCase()}</span>
      </button>
      {open && (
        <ul className="lang-menu" role="listbox">
          {LANGUAGES.map((l) => (
            <li key={l.code} role="presentation">
              <button type="button" className="lang-option" role="option" aria-selected={language === l.code} onClick={() => { changeLanguage(l.code); setOpen(false); }}>
                {l.name}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default function Navbar() {
  const { t } = useLanguage();
  const pathname = usePathname();
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') setMenuOpen(false); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);

  return (
    <header className="site-header">
      <div className="container header-inner">
        <Link href="/" className="logo">
          <img src="/logo-icon.png" alt="" className="logo-img" />
          <span>VeriWork</span>
        </Link>

        <nav className="main-nav" aria-label="Primary">
          <ul className="nav-list">
            {NAV.map((item) => (
              <li key={item.key}>
                <Link className="nav-link" href={item.href} aria-current={item.href === '/' && pathname === '/' ? 'page' : undefined}>{t(item.key)}</Link>
              </li>
            ))}
          </ul>
        </nav>

        <div className="header-right">
          <LangSwitch />
          <ThemeToggle />
          <Link className="btn btn-ghost header-auth" href="/login">{t('auth.login')}</Link>
          <Link className="btn btn-primary header-auth" href="/signup">{t('auth.signup')}</Link>
          <button type="button" className="menu-toggle" aria-expanded={menuOpen} aria-controls="mobile-menu" onClick={() => setMenuOpen(!menuOpen)}>
            {menuOpen ? t('nav.close') : t('nav.menu')}
          </button>
        </div>
      </div>

      {menuOpen && (
        <div id="mobile-menu" className="mobile-menu">
          <nav aria-label="Mobile">
            <ul>
              {NAV.map((item) => (
                <li key={item.key}><Link className="mobile-nav-link" href={item.href} onClick={() => setMenuOpen(false)}>{t(item.key)}</Link></li>
              ))}
            </ul>
          </nav>
          <div className="mobile-actions">
            <Link className="btn btn-ghost" href="/login" onClick={() => setMenuOpen(false)}>{t('auth.login')}</Link>
            <Link className="btn btn-primary" href="/signup" onClick={() => setMenuOpen(false)}>{t('auth.signup')}</Link>
          </div>
        </div>
      )}
    </header>
  );
}
